#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    bool solve(string s) {
        stack<char> st;
        for(char c:s){
            if(c=='('||c=='{'||c=='[') st.push(c);
            else {
                if(st.empty()) return false;
                if(c==')' && st.top()!='(') return false;
                if(c=='}' && st.top()!='{') return false;
                if(c==']' && st.top()!='[') return false;
                st.pop();
            }
        }
        return st.empty();
    }
};
int main() {
    string s;
    if(!(cin >> s)) s = "";
    Solution obj;
    cout << (obj.solve(s) ? "true" : "false") << endl;
    return 0;
}

